package main

// Probes for task plsqlfull: PL/pgSQL completeness (overloading, OUT/DEFAULT parameters, set-returning
// functions, cursors, records, diagnostics), INSTEAD OF / transition-table / TRUNCATE triggers, COLLATE
// in definitions, CREATE COLLATION (docs/14 Appendix Z). The expected values are PostgreSQL 16's; the
// same probes were run against postgres:16 (claimcheck -url on a postgres:16 server).

func init() {
	const dropOv = "~DROP FUNCTION IF EXISTS cc_ov(int); DROP FUNCTION IF EXISTS cc_ov(text); DROP FUNCTION IF EXISTS cc_ov(int, int)"
	ov := []string{dropOv,
		"CREATE FUNCTION cc_ov(a int) RETURNS text AS $f$ SELECT 'int' $f$ LANGUAGE sql",
		"CREATE FUNCTION cc_ov(a text) RETURNS text AS $f$ SELECT 'text' $f$ LANGUAGE sql",
		"CREATE FUNCTION cc_ov(a int, b int) RETURNS text AS $f$ SELECT 'two' $f$ LANGUAGE sql"}
	with := func(pre []string, more ...string) []string { return append(append([]string(nil), pre...), more...) }
	extraChecks = append(extraChecks,
		check{"pf_overload_by_argument_type", "plsqlfull", "05 §18", with(ov, "SELECT cc_ov(1) || cc_ov('x'::text) || cc_ov(1, 2)"), "val:inttexttwo", nil},
		check{"pf_overload_no_match", "plsqlfull", "05 §18", with(ov, "SELECT cc_ov(1.5)"), "err:42883", nil},
		check{"pf_overload_create_same_signature", "plsqlfull", "05 §18", with(ov, "CREATE FUNCTION cc_ov(a int) RETURNS text AS $f$ SELECT 'dup' $f$ LANGUAGE sql"), "err:42723", nil},
		check{"pf_overload_drop_by_types", "plsqlfull", "05 §18", with(ov, "DROP FUNCTION cc_ov(text)", "SELECT cc_ov(1) || cc_ov(1, 2)"), "val:inttwo", nil},
		check{"pf_overload_pg_proc_rows", "plsqlfull", "05 §18", with(ov, "SELECT count(*) FROM pg_proc WHERE proname = 'cc_ov'"), "val:3", nil},
		check{"pf_out_parameters_in_from", "plsqlfull", "05 §18", []string{"CREATE OR REPLACE FUNCTION cc_mm(a int, b int, OUT lo int, OUT hi int) AS $f$ BEGIN lo := least(a,b); hi := greatest(a,b); END $f$ LANGUAGE plpgsql",
			"SELECT hi || '/' || lo FROM cc_mm(5, 3)"}, "val:5/3", nil},
		check{"pf_out_parameters_scalar_context", "plsqlfull", "05 §18", []string{"CREATE OR REPLACE FUNCTION cc_mm(a int, b int, OUT lo int, OUT hi int) AS $f$ BEGIN lo := least(a,b); hi := greatest(a,b); END $f$ LANGUAGE plpgsql",
			"SELECT cc_mm(7, 2)"}, "val:(2,7)", nil},
		check{"pf_default_and_named_arguments", "plsqlfull", "05 §18", []string{"CREATE OR REPLACE FUNCTION cc_df(a int, b int DEFAULT 10, c text DEFAULT 'z') RETURNS text AS $f$ BEGIN RETURN a || '-' || b || '-' || c; END $f$ LANGUAGE plpgsql",
			"SELECT cc_df(1) || ',' || cc_df(1, 2) || ',' || cc_df(a => 5, c => 'k')"}, "val:1-10-z,1-2-z,5-10-k", nil},
		check{"pf_function_integer_result_type", "plsqlfull", "05 §18", []string{"CREATE OR REPLACE FUNCTION cc_i() RETURNS integer AS $f$ BEGIN RETURN 5; END $f$ LANGUAGE plpgsql",
			"SELECT pg_typeof(cc_i())::text"}, "val:integer", nil},
		check{"pf_returns_table_and_return_query", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT)", "INSERT INTO cc_t VALUES (1,'a'),(2,'b'),(3,'c')",
			"CREATE OR REPLACE FUNCTION cc_rq() RETURNS TABLE(id int, n text) AS $f$ BEGIN RETURN QUERY SELECT t.id::int, t.n FROM cc_t t ORDER BY t.id; END $f$ LANGUAGE plpgsql",
			"SELECT string_agg(n, ',' ORDER BY id) FROM cc_rq() WHERE id > 1"}, "val:b,c", nil},
		check{"pf_setof_return_next_in_from_and_select_list", "plsqlfull", "05 §18", []string{"CREATE OR REPLACE FUNCTION cc_rn(n int) RETURNS SETOF int AS $f$ BEGIN FOR i IN 1..n LOOP RETURN NEXT i * i; END LOOP; RETURN; END $f$ LANGUAGE plpgsql",
			"SELECT (SELECT sum(x) FROM cc_rn(4) x)::text || ',' || (SELECT count(*) FROM (SELECT cc_rn(3)) q)::text"}, "val:30,3", nil},
		check{"pf_cursor_open_fetch_close", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT)", "INSERT INTO cc_t VALUES (1,'a'),(2,'b'),(3,'c')",
			"CREATE OR REPLACE FUNCTION cc_cur() RETURNS text AS $f$ DECLARE c CURSOR FOR SELECT id, n FROM cc_t ORDER BY id; r record; s text := ''; BEGIN OPEN c; LOOP FETCH c INTO r; EXIT WHEN NOT FOUND; s := s || r.id || r.n; END LOOP; CLOSE c; RETURN s; END $f$ LANGUAGE plpgsql",
			"SELECT cc_cur()"}, "val:1a2b3c", nil},
		check{"pf_for_over_cursor_with_arguments", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT)", "INSERT INTO cc_t VALUES (1,'a'),(2,'b'),(3,'c')",
			"CREATE OR REPLACE FUNCTION cc_cur2(m int) RETURNS int AS $f$ DECLARE c CURSOR (lim int) FOR SELECT id FROM cc_t WHERE id <= lim ORDER BY id; r record; t int := 0; BEGIN FOR r IN c(m) LOOP t := t + r.id; END LOOP; RETURN t; END $f$ LANGUAGE plpgsql",
			"SELECT cc_cur2(2)"}, "val:3", nil},
		check{"pf_get_diagnostics_row_count_and_found", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT)",
			"CREATE OR REPLACE FUNCTION cc_gd() RETURNS text AS $f$ DECLARE n int; m int; f boolean; BEGIN INSERT INTO cc_t SELECT g, 'x' FROM generate_series(1,5) g; GET DIAGNOSTICS n = ROW_COUNT; UPDATE cc_t SET n = 'y' WHERE id > 2; GET DIAGNOSTICS m = ROW_COUNT; UPDATE cc_t SET n = 'z' WHERE id > 100; f := FOUND; RETURN n || '/' || m || '/' || f; END $f$ LANGUAGE plpgsql",
			"SELECT cc_gd()"}, "val:5/3/false", nil},
		check{"pf_foreach_array", "plsqlfull", "05 §18", []string{"CREATE OR REPLACE FUNCTION cc_fe(a int[]) RETURNS int AS $f$ DECLARE s int := 0; x int; BEGIN FOREACH x IN ARRAY a LOOP s := s + x; END LOOP; RETURN s; END $f$ LANGUAGE plpgsql",
			"SELECT cc_fe(ARRAY[1,2,3,4])"}, "val:10", nil},
		check{"pf_record_rowtype_and_to_jsonb", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT)", "INSERT INTO cc_t VALUES (1,'a')",
			"CREATE OR REPLACE FUNCTION cc_rec() RETURNS text AS $f$ DECLARE r cc_t; BEGIN SELECT * INTO r FROM cc_t WHERE id = 1; RETURN to_jsonb(r)::text || r.n; END $f$ LANGUAGE plpgsql",
			"SELECT cc_rec()"}, "val:{\"n\": \"a\", \"id\": 1}a", nil},
		check{"pf_to_jsonb_of_row_alias", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT)", "INSERT INTO cc_t VALUES (1,'a'),(2,'b')",
			"SELECT jsonb_agg(t ORDER BY id)::text FROM cc_t t"}, "val:[{\"n\": \"a\", \"id\": 1}, {\"n\": \"b\", \"id\": 2}]", nil},
		check{"pf_stacked_diagnostics_detail_hint", "plsqlfull", "05 §18", []string{"CREATE OR REPLACE FUNCTION cc_se() RETURNS text AS $f$ DECLARE m text; d text; h text; BEGIN RAISE EXCEPTION 'boom %', 1 USING ERRCODE = '22012', DETAIL = 'dd', HINT = 'hh'; EXCEPTION WHEN division_by_zero THEN GET STACKED DIAGNOSTICS m = MESSAGE_TEXT, d = PG_EXCEPTION_DETAIL, h = PG_EXCEPTION_HINT; RETURN m || d || h || SQLSTATE; END $f$ LANGUAGE plpgsql",
			"SELECT cc_se()"}, "val:boom 1ddhh22012", nil},
		check{"pf_assert_failure", "plsqlfull", "05 §18", []string{"CREATE OR REPLACE FUNCTION cc_as() RETURNS int AS $f$ BEGIN ASSERT 1 = 2, 'no'; RETURN 1; END $f$ LANGUAGE plpgsql", "SELECT cc_as()"}, "err:P0004", nil},
		check{"pf_no_return_is_an_error", "plsqlfull", "05 §18", []string{"CREATE OR REPLACE FUNCTION cc_nr() RETURNS int AS $f$ BEGIN NULL; END $f$ LANGUAGE plpgsql", "SELECT cc_nr()"}, "err:2F005", nil},
		check{"pf_dynamic_execute_format_using", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT)",
			"CREATE OR REPLACE FUNCTION cc_dy(tbl text, i int) RETURNS int AS $f$ DECLARE c int; BEGIN EXECUTE format('INSERT INTO %I VALUES ($1, $2)', tbl) USING i, 'v'; EXECUTE format('SELECT count(*) FROM %I WHERE id >= $1', tbl) INTO c USING 0; RETURN c; END $f$ LANGUAGE plpgsql",
			"SELECT cc_dy('cc_t', 1) + cc_dy('cc_t', 2)"}, "val:3", nil},
		check{"pf_function_writes_roll_back_with_statement", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT)",
			"CREATE OR REPLACE FUNCTION cc_w(i int) RETURNS int AS $f$ BEGIN INSERT INTO cc_t VALUES (i, 'w'); IF i > 1 THEN RAISE EXCEPTION 'no'; END IF; RETURN 1; END $f$ LANGUAGE plpgsql",
			"~SELECT cc_w(1), cc_w(2)", "SELECT count(*) FROM cc_t"}, "val:0", nil},
		check{"pf_function_writes_commit_with_statement", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT)",
			"CREATE OR REPLACE FUNCTION cc_w(i int) RETURNS int AS $f$ BEGIN INSERT INTO cc_t VALUES (i, 'w'); RETURN 1; END $f$ LANGUAGE plpgsql",
			"SELECT cc_w(g) FROM generate_series(1, 3) g", "SELECT count(*) FROM cc_t"}, "val:3", nil},
		check{"pf_procedure_inout_call_returns_row", "plsqlfull", "05 §18", []string{"CREATE OR REPLACE PROCEDURE cc_pr(a int, INOUT b text) AS $f$ BEGIN b := b || a; END $f$ LANGUAGE plpgsql",
			"CALL cc_pr(1, 'x')"}, "ok", nil},
		check{"pf_instead_of_trigger_on_view", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT)", "CREATE VIEW cc_v AS SELECT id, upper(n) AS un FROM cc_t",
			"CREATE OR REPLACE FUNCTION cc_iv() RETURNS trigger AS $f$ BEGIN INSERT INTO cc_t VALUES (NEW.id, lower(NEW.un)); RETURN NEW; END $f$ LANGUAGE plpgsql",
			"CREATE TRIGGER cc_iv_trg INSTEAD OF INSERT ON cc_v FOR EACH ROW EXECUTE FUNCTION cc_iv()", "INSERT INTO cc_v VALUES (1, 'ABC')", "SELECT n FROM cc_t"}, "val:abc", nil},
		check{"pf_instead_of_on_table_is_an_error", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT)",
			"CREATE OR REPLACE FUNCTION cc_iv() RETURNS trigger AS $f$ BEGIN RETURN NEW; END $f$ LANGUAGE plpgsql",
			"CREATE TRIGGER cc_iv_trg INSTEAD OF INSERT ON cc_t FOR EACH ROW EXECUTE FUNCTION cc_iv()"}, "err:42809", nil},
		check{"pf_transition_tables", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n BIGINT)", "CREATE TABLE cc_c (id BIGINT PRIMARY KEY, n BIGINT)",
			"CREATE OR REPLACE FUNCTION cc_tt() RETURNS trigger AS $f$ BEGIN INSERT INTO cc_c SELECT 1, sum(n) FROM newrows; RETURN NULL; END $f$ LANGUAGE plpgsql",
			"CREATE TRIGGER cc_tt_trg AFTER INSERT ON cc_t REFERENCING NEW TABLE AS newrows FOR EACH STATEMENT EXECUTE FUNCTION cc_tt()",
			"INSERT INTO cc_t VALUES (1,10),(2,20),(3,30)", "SELECT n FROM cc_c"}, "val:60", nil},
		check{"pf_truncate_trigger", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n BIGINT)", "CREATE TABLE cc_c (id BIGINT PRIMARY KEY, n BIGINT)", "INSERT INTO cc_t VALUES (1,1)",
			"CREATE OR REPLACE FUNCTION cc_tr() RETURNS trigger AS $f$ BEGIN INSERT INTO cc_c VALUES (1, 7); RETURN NULL; END $f$ LANGUAGE plpgsql",
			"CREATE TRIGGER cc_tr_trg AFTER TRUNCATE ON cc_t FOR EACH STATEMENT EXECUTE FUNCTION cc_tr()", "TRUNCATE cc_t", "SELECT n FROM cc_c"}, "val:7", nil},
		check{"pf_trigger_whole_new_row_to_jsonb", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT)", "CREATE TABLE cc_c (id BIGINT PRIMARY KEY, n TEXT)",
			"CREATE OR REPLACE FUNCTION cc_aud() RETURNS trigger AS $f$ BEGIN INSERT INTO cc_c VALUES (NEW.id, to_jsonb(NEW)::text); RETURN NEW; END $f$ LANGUAGE plpgsql",
			"CREATE TRIGGER cc_aud_trg AFTER INSERT ON cc_t FOR EACH ROW EXECUTE FUNCTION cc_aud()", "INSERT INTO cc_t VALUES (1, 'a')", "SELECT n FROM cc_c"}, "val:{\"n\": \"a\", \"id\": 1}", nil},
		check{"pf_collate_on_column_orders_by_it", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT COLLATE \"C\", m TEXT COLLATE \"en_US\")",
			"INSERT INTO cc_t VALUES (1,'b','b'),(2,'A','A'),(3,'a','a')",
			"SELECT (SELECT n FROM cc_t ORDER BY n LIMIT 1) || (SELECT m FROM cc_t ORDER BY m LIMIT 1)"}, "val:Aa", nil},
		check{"pf_collate_on_column_range", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT COLLATE \"C\", m TEXT COLLATE \"en_US\")",
			"INSERT INTO cc_t VALUES (1,'b','b'),(2,'A','A'),(3,'a','a')",
			"SELECT (SELECT count(*) FROM cc_t WHERE n > 'a') || ',' || (SELECT count(*) FROM cc_t WHERE m > 'a')"}, "val:1,2", nil},
		check{"pf_collate_unknown_in_column", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT COLLATE \"no_such_collation\")"}, "err:42704", nil},
		check{"pf_collate_in_index_definition", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT)", "CREATE INDEX cc_t_n ON cc_t (n COLLATE \"C\")",
			"SELECT indexdef FROM pg_indexes WHERE indexname = 'cc_t_n'"}, "val:CREATE INDEX cc_t_n ON public.cc_t USING btree (n COLLATE \"C\")", nil},
		check{"pf_collate_attcollation_and_information_schema", "plsqlfull", "05 §18", []string{"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT COLLATE \"C\")",
			"SELECT collation_name FROM information_schema.columns WHERE table_name = 'cc_t' AND column_name = 'n'"}, "val:C", nil},
		check{"pf_create_collation_and_use_it", "plsqlfull", "05 §18", []string{"~DROP TABLE IF EXISTS cc_t", "~DROP COLLATION IF EXISTS cc_bytes", "CREATE COLLATION cc_bytes (provider = libc, locale = 'C')",
			"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT COLLATE cc_bytes)", "INSERT INTO cc_t VALUES (1,'b'),(2,'A'),(3,'a')",
			"SELECT (SELECT n FROM cc_t ORDER BY n LIMIT 1) || (SELECT count(*) FROM pg_collation WHERE collname = 'cc_bytes')"}, "val:A1", nil},
		check{"pf_drop_collation_in_use", "plsqlfull", "05 §18", []string{"~DROP TABLE IF EXISTS cc_t", "~DROP COLLATION IF EXISTS cc_bytes", "CREATE COLLATION cc_bytes (provider = libc, locale = 'C')",
			"CREATE TABLE cc_t (id BIGINT PRIMARY KEY, n TEXT COLLATE cc_bytes)", "DROP COLLATION cc_bytes"}, "err:2BP01", nil},
		check{"pf_regprocedure_and_regtype_text", "plsqlfull", "05 §18", []string{"CREATE OR REPLACE FUNCTION cc_rp(a int, b text) RETURNS text AS $f$ SELECT b $f$ LANGUAGE sql",
			"SELECT (SELECT oid::regprocedure::text FROM pg_proc WHERE proname = 'cc_rp') || ',' || (SELECT prorettype::regtype::text FROM pg_proc WHERE proname = 'cc_rp')"}, "val:cc_rp(integer,text),text", nil},
		check{"pf_pg_get_function_arguments_with_defaults", "plsqlfull", "05 §18", []string{"CREATE OR REPLACE FUNCTION cc_ad(a int, b text DEFAULT 'x', OUT c int) AS $f$ BEGIN c := a; END $f$ LANGUAGE plpgsql",
			"SELECT pg_get_function_arguments(oid) || '|' || pg_get_function_identity_arguments(oid) || '|' || pg_get_function_result(oid) FROM pg_proc WHERE proname = 'cc_ad'"},
			"val:a integer, b text DEFAULT 'x'::text, OUT c integer|a integer, b text, OUT c integer|integer", nil},
		check{"pf_pg_language_rows", "plsqlfull", "05 §18", []string{"SELECT string_agg(lanname, ',' ORDER BY lanname) FROM pg_language WHERE lanname IN ('sql', 'plpgsql', 'c', 'internal')"}, "val:c,internal,plpgsql,sql", nil},
	)
}
